import React, {
  Fragment,
  useMemo,
  ReactElement,
  FC,
  ReactChildren,
} from "react";
import {
  observer,
  RecursionField,
  useField,
  useFieldSchema,
  useForm,
} from "@formily/react";
import {
  FormStepDecoratorProps,
  FormStepProps,
  StepPaneProps,
  IFormStep,
} from "./types";
import { parseSchemaSteps } from "./shared/parseSchemaSteps";
import { Steps } from "@arco-design/web-react";
import StepPane from "./StepPane";
import { DefaultFormStepDecorator } from "./decorator/DefaultFormStepDecorator";
import { parseJSXSteps } from "./shared/parseJSXSteps";
import { VoidField as VoidFieldType } from "@formily/core";
import { isFunction } from "@arco-design/web-react/es/_util/is";
import { createFormStep } from "./shared/createFormStep";
import {
  TopSlot,
  HeaderSlot,
  ButtonsSlot,
  ResidentContentSlot,
  FooterSlot,
  ArcoStepsSlot,
  getSlot,
} from "./shared/slot";
import { FormStepContext } from "./shared/context";
import BackButton from "./buttons/back";
import NextButton from "./buttons/next";
import SubmitButton from "./buttons/submit";
export * from "./types";

type ComposeFormStep = FC<FormStepProps> & {
  StepPane: typeof StepPane;
  HeaderSlot: typeof HeaderSlot;
  TopSlot: typeof TopSlot;
  ButtonsSlot: typeof ButtonsSlot;
  ResidentContentSlot: typeof ResidentContentSlot;
  FooterSlot: typeof FooterSlot;
  ArcoStepsSlot: typeof ArcoStepsSlot;
  createFormStep: (defaultCurrent?: number) => IFormStep;
  Decorator: Record<"DefaultFormStepDecorator", FC<FormStepDecoratorProps>>;
  createFormStepFunction: (defaultCurrent?: number) => any;
  BackButton: typeof BackButton;
  NextButton: typeof NextButton;
  SubmitButton: typeof SubmitButton;
};

export const renderSchemaSteps = (props: FormStepProps) => {
  const { formStep } = props;
  const form = useForm();

  const current = props.current || formStep?.current || 0;
  const field = useField<VoidFieldType>();
  const schema = useFieldSchema();
  const steps = parseSchemaSteps(schema);
  formStep?.connect?.({
    form,
    mode: props.mode,
    steps,
    beforeStepChange: props.beforeStepChange,
    onStepChange: props.onStepChange,
  });

  const stepContent = (
    <Fragment>
      {steps.map(({ name, schema }, key) => {
        if (key !== current) {
          return;
        }
        return <RecursionField key={key} name={name} schema={schema} />;
      })}
    </Fragment>
  );
  return {
    stepContent,
    stepsProps: steps?.map((v) => v.props).filter(Boolean),
  };
};

export const renderJSXSteps = (props: FormStepProps) => {
  const steps = parseJSXSteps(props.children as ReactChildren);
  const stepsProps = steps
    .map((child) => child?.props)
    .filter(Boolean)
    .map((item) => {
      const [_, props] = item.component;
      return {
        name: item.name,
        ...props,
      };
    });

  const { formStep } = props;
  const form = useForm();
  const current = props.current || formStep?.current || 0;

  formStep?.connect?.({
    form,
    mode: props.mode,
    // 只需每个 step name 即可
    steps: stepsProps.map(({ name }) => ({
      name,
    })),
    beforeStepChange: props.beforeStepChange,
    onStepChange: props.onStepChange,
  });
  const stepContent = steps?.[current];
  return {
    stepContent,
    stepsProps,
  };
};

export const renderDecorator = (
  params: {
    decorator: FormStepProps["decorator"];
  } & FormStepDecoratorProps
) => {
  const [Decorator = DefaultFormStepDecorator, decoratorProps = {}] =
    params.decorator || [];

  const {
    footerSlot,
    topSlot,
    headerSlot,
    arcoSteps,
    steps,
    buttonsSlot,
    residentContentSlot,
    className,
    style,
    prefixCls,
  } = params;

  return (
    <Decorator
      footerSlot={footerSlot}
      prefixCls={prefixCls}
      topSlot={topSlot}
      headerSlot={headerSlot}
      arcoSteps={arcoSteps}
      steps={steps}
      buttonsSlot={buttonsSlot}
      residentContentSlot={residentContentSlot}
      className={className}
      style={style}
      {...decoratorProps}
    />
  );
};

export const renderArcoSteps = (
  stepsProps: FormStepProps["arcoStepsProps"],
  steps: StepPaneProps[],
  formStep: IFormStep
) => {
  const _arcoStepsProps =
    (isFunction(stepsProps) ? stepsProps?.(formStep) : stepsProps) || {};
  // Arco Steps 1 为第一步，故需要 +1
  const current = formStep.current + 1;
  return (
    <Steps
      {..._arcoStepsProps}
      style={{ ..._arcoStepsProps?.style }}
      current={current}
    >
      {steps.map((props, key) => (
        <Steps.Step {...props} key={key} />
      ))}
    </Steps>
  );
};

const _FormStep: React.FC<FormStepProps> = observer((props) => {
  const {
    mode = "JSX",
    current,
    decorator,
    arcoStepsProps,
    showArcoSteps = true,
  } = props;
  const formStep = props.formStep || useMemo(() => createFormStep(current), []);
  const { stepContent, stepsProps } =
    mode === "Schema"
      ? renderSchemaSteps(props)
      : renderJSXSteps({ ...props, formStep });

  const headerSlot = getSlot(props, "header", formStep);
  const topSlot = getSlot(props, "top", formStep);
  const residentContentSlot = getSlot(props, "residentContent", formStep);
  const buttonsSlot = getSlot(props, "buttons", formStep);
  const footerSlot = getSlot(props, "footer", formStep);
  const arcoSteps = showArcoSteps
    ? renderArcoSteps(arcoStepsProps, stepsProps, formStep)
    : null;

  const content = renderDecorator({
    decorator,
    headerSlot,
    topSlot,
    residentContentSlot,
    buttonsSlot,
    footerSlot,
    arcoSteps,
    steps: stepContent,
  });

  return (
    <FormStepContext.Provider value={formStep}>
      {content}
    </FormStepContext.Provider>
  );
});

const FormStep: ComposeFormStep = _FormStep as ComposeFormStep;
FormStep.displayName = "FormStep";

FormStep.createFormStep = createFormStep;
FormStep.ButtonsSlot = ButtonsSlot;
FormStep.FooterSlot = FooterSlot;
FormStep.ResidentContentSlot = ResidentContentSlot;
FormStep.TopSlot = TopSlot;
FormStep.HeaderSlot = HeaderSlot;
FormStep.ArcoStepsSlot = ArcoStepsSlot;
FormStep.StepPane = StepPane;
FormStep.Decorator = {
  DefaultFormStepDecorator,
};
FormStep.NextButton = NextButton;
FormStep.SubmitButton = SubmitButton;
FormStep.BackButton = BackButton;

export default FormStep;
